// Node 7 - Validate & Enforce Safety (actions/ETF only)

function isObj(x) { return x && typeof x === "object" && !Array.isArray(x); }
function safeJsonParse(s) { try { return JSON.parse(s); } catch { return null; } }
function toNumOrNull(x) { const n = Number(x); return Number.isFinite(n) ? n : null; }
function toNum(x, dflt = 0) { const n = Number(x); return Number.isFinite(n) ? n : dflt; }
function normSymbol(v) { return String(v ?? "").trim().toUpperCase(); }
function clampText(v, max = 0) {
  const s = String(v ?? "").replace(/\s+/g, " ").trim();
  return max > 0 ? s.slice(0, max) : s;
}

function normAssetClass(v) {
  const raw = String(v ?? "").trim().toUpperCase();
  if (raw === "ETF") return "ETF";
  if (raw === "EQUITY" || raw === "STK" || raw === "STOCK" || !raw) return "EQUITY";
  return raw;
}

function deepClone(obj) { try { return JSON.parse(JSON.stringify(obj)); } catch { return obj; } }

function cfgNumber(config, keys, dflt) {
  for (const key of keys) {
    const n = toNumOrNull(config?.[key]);
    if (n !== null) return n;
  }
  return dflt;
}

function cfgBool(config, keys, dflt = false) {
  for (const key of keys) {
    if (config?.[key] === undefined || config?.[key] === null) continue;
    const s = String(config[key]).trim().toLowerCase();
    if (["1", "true", "yes", "y", "on", "enabled"].includes(s)) return true;
    if (["0", "false", "no", "n", "off", "disabled"].includes(s)) return false;
  }
  return dflt;
}

function pick(row, ...keys) {
  for (const key of keys) {
    const v = row?.[key];
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return null;
}

function extractAgentDecisionObject(input) {
  let decisionRaw = null;

  if (isObj(input.output) && Array.isArray(input.output.actions)) return { ...input.output, _parseStatus: "OK_OBJECT_OUTPUT" };
  if (isObj(input.agentDecision)) return { ...input.agentDecision, _parseStatus: "OK_AGENTDECISION" };
  if (Array.isArray(input.output) && input.output.length > 0 && input.output.every((x) => isObj(x) && String(x.action ?? "").length)) {
    return { actions: input.output, dataCaveats: [], backfillRequests: [], _parseStatus: "OK_ACTIONS_ARRAY_OUTPUT" };
  }

  if (typeof input.output === "string") decisionRaw = input.output;
  else if (input.output?.text) decisionRaw = input.output.text;
  else if (Array.isArray(input.output) && input.output[0]?.content?.[0]?.text) decisionRaw = input.output[0].content[0].text;
  else if (input.text) decisionRaw = input.text;

  if (typeof decisionRaw === "string") {
    let cleaned = decisionRaw.trim();
    if (cleaned.includes("```")) {
      const parts = cleaned.split("```");
      if (parts.length >= 3) {
        cleaned = parts[1];
        if (cleaned.toLowerCase().startsWith("json")) cleaned = cleaned.substring(4).trim();
      }
    }
    const firstBrace = cleaned.indexOf("{");
    const lastBrace = cleaned.lastIndexOf("}");
    if (firstBrace !== -1 && lastBrace !== -1) cleaned = cleaned.substring(firstBrace, lastBrace + 1);

    const parsed = safeJsonParse(cleaned);
    if (isObj(parsed)) return { ...parsed, _parseStatus: "OK_CLEANED_JSON" };
    return { _rawText: decisionRaw, _parseStatus: "TEXT_NOT_JSON" };
  }

  return { _parseStatus: "MISSING_DECISION", _why: "No decision payload found." };
}

function coerceAgentDecisionToExpectedShape(agentDecision) {
  if (!isObj(agentDecision)) return { _parseStatus: "NOT_OBJECT", actions: [], dataCaveats: [], backfillRequests: [] };
  const d = deepClone(agentDecision);
  if (!Array.isArray(d.actions)) d.actions = [];
  if (!Array.isArray(d.dataCaveats)) d.dataCaveats = [];
  if (!Array.isArray(d.backfillRequests)) d.backfillRequests = [];
  return d;
}

function normalizeOrderType(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (s === "LMT" || s === "LIMIT") return "LIMIT";
  if (s === "MKT" || s === "MARKET") return "MARKET";
  return s || "MARKET";
}

function inferQtyFromWeightPct(portfolioSummary, weightPct, priceHint) {
  const tv = toNum(portfolioSummary?.totalPortfolioValueEUR, 0);
  const w = toNumOrNull(weightPct);
  const px = toNumOrNull(priceHint);
  if (!tv || !w || !px || px <= 0) return null;
  const eur = tv * (w / 100.0);
  const q = Math.floor(eur / px);
  return Number.isFinite(q) && q > 0 ? q : null;
}

function actionDataAge(action, keyVariants) {
  for (const key of keyVariants) {
    const n = toNumOrNull(action?.[key]);
    if (n !== null) return n;
  }
  return null;
}

function actionFlagText(action) {
  const raw = action?.dataQualityFlags ?? action?.Data_Quality_Flags ?? action?.data_quality_flags ?? "";
  return Array.isArray(raw) ? raw.join(",") : String(raw || "");
}

const input = $json ?? {};
const transfer_pack = input.transfer_pack || {};
const final_db_path = transfer_pack.db_path || input.db_path || "";

const portfolioSummary =
  input.portfolioSummary ??
  input.ctx?.portfolioSummary ??
  transfer_pack.portfolioSummary ??
  { cashEUR: 0, totalPortfolioValueEUR: null, positions: [] };

const configRaw = input.config ?? input.ctx?.config ?? transfer_pack.config ?? {};
const ts = new Date().toISOString();
const runId = String(input?.run?.runId ?? input?.runId ?? transfer_pack?.run?.runId ?? "").trim() || `RUN_${Date.now()}`;
const model = String(input?.run?.model ?? transfer_pack?.run?.model ?? "UNKNOWN").trim();

const limits = {
  maxPosPct: cfgNumber(configRaw, ["max_pos_pct", "maxPositionPct", "max_position_pct"], 25),
  maxSectorPct: cfgNumber(configRaw, ["max_sector_pct", "maxSectorPct"], 40),
  maxOrderValuePct: cfgNumber(configRaw, ["max_order_value_pct", "maxOrderValuePct"], 15),
  minOrderValueEUR: cfgNumber(configRaw, ["min_order_value_eur", "minOrderValueEUR"], 1000),
  maxOpenPositions: cfgNumber(configRaw, ["max_open_positions", "maxOpenPositions"], 10),
  defaultFeeBps: cfgNumber(configRaw, ["default_fee_bps", "fee_bps", "defaultFeeBps"], 10),
  maxSpreadPct: cfgNumber(configRaw, ["max_spread_pct", "maxSpreadPct"], 1.5),
  maxH1AgeHours: cfgNumber(configRaw, ["max_h1_age_hours", "maxH1AgeHours"], 96),
  maxD1AgeHours: cfgNumber(configRaw, ["max_d1_age_hours", "maxD1AgeHours"], 240),
  requireLimitBuys: cfgBool(configRaw, ["require_limit_buys", "requireLimitBuys"], true),
  killSwitchActive: cfgBool(configRaw, ["kill_switch_active", "killSwitchActive"], false),
};

let agentDecision = extractAgentDecisionObject(input);
agentDecision = coerceAgentDecisionToExpectedShape(agentDecision);

const execSet = new Set(["OPEN", "INCREASE", "DECREASE", "CLOSE"]);
const posList = Array.isArray(portfolioSummary?.positions) ? portfolioSummary.positions : [];
const posQty = {};
const posLast = {};
const posSector = {};
const posMarketValue = {};
let inferredEquity = 0;
for (const p of posList) {
  const s = normSymbol(pick(p, "Symbol", "symbol"));
  if (!s || s === "CASH_EUR" || s === "__META__") continue;
  const qty = toNum(pick(p, "Quantity", "quantity", "qty"), 0);
  const px = toNumOrNull(pick(p, "LastPrice", "lastPrice", "price"));
  const mv = toNum(pick(p, "MarketValue", "marketValue", "market_value", "MarketValueEUR", "marketValueEUR", "value"), qty * (px || 0));
  posQty[s] = qty;
  posLast[s] = px;
  posSector[s] = clampText(pick(p, "Sector", "sector") || "UNKNOWN", 128) || "UNKNOWN";
  posMarketValue[s] = mv;
  inferredEquity += Math.max(0, mv);
}

const cashEUR = toNum(portfolioSummary?.cashEUR, 0);
const portfolioValue = toNum(portfolioSummary?.totalPortfolioValueEUR, cashEUR + inferredEquity) || Math.max(1, cashEUR + inferredEquity);
// Nombre de lignes distinctes reellement detenues (pour plafonner les nouvelles ouvertures).
const openPositionsCount = Object.values(posQty).filter((q) => toNum(q, 0) > 0).length;
const sectorValue = {};
for (const [sym, mv] of Object.entries(posMarketValue)) {
  const sector = posSector[sym] || "UNKNOWN";
  sectorValue[sector] = (sectorValue[sector] || 0) + Math.max(0, mv);
}

const orders = [];
const warnings = [];
const rejects = [];

function reject(symbol, code, detail = "") {
  const msg = `ORDER_REJECT:${code}:${symbol}${detail ? `:${detail}` : ""}`;
  warnings.push(msg);
  rejects.push(msg);
}

for (const a of agentDecision.actions || []) {
  const action = String(a.action || "").toUpperCase();
  if (!execSet.has(action)) continue;

  const symbol = normSymbol(a.symbol_internal || a.symbol);
  if (!symbol || symbol === "CASH_EUR" || symbol === "__META__") { reject("UNKNOWN", "NO_SYMBOL"); continue; }
  if (String(a.symbol_yahoo || "").toUpperCase().endsWith("=X") || symbol.startsWith("F" + "X:")) {
    reject(symbol, "UNSUPPORTED_ASSET");
    continue;
  }

  const assetClass = normAssetClass(a.assetClass ?? a.AssetClass);
  if (!["EQUITY", "ETF"].includes(assetClass)) {
    reject(symbol, "UNSUPPORTED_ASSET_CLASS", assetClass);
    continue;
  }

  const currentQty = toNum(posQty[symbol], 0);
  const limitPx = toNumOrNull(a.entryPlan?.limitPrice ?? a.limitPrice);
  const lastPx = toNumOrNull(posLast[symbol]);
  const priceHint = limitPx ?? toNumOrNull(a.priceHint) ?? lastPx;
  let qty = null;

  if (action === "CLOSE") {
    qty = currentQty;
  } else if (action === "DECREASE") {
    const targetFinal = toNumOrNull(a.targetQty);
    if (targetFinal === null) { reject(symbol, "DECREASE_NO_TARGETQTY"); continue; }
    qty = Math.max(0, currentQty - targetFinal);
  } else if (action === "INCREASE") {
    const targetFinal = toNumOrNull(a.targetQty);
    if (targetFinal === null) { reject(symbol, "INCREASE_NO_TARGETQTY"); continue; }
    if (currentQty <= 0) {
      qty = Math.max(0, targetFinal);
      if (qty > 0) a.__normalized_action = "OPEN";
    } else {
      qty = Math.max(0, targetFinal - currentQty);
    }
  } else if (action === "OPEN") {
    const tq = toNumOrNull(a.targetQty);
    qty = tq !== null && tq > 0 ? tq : inferQtyFromWeightPct(portfolioSummary, a.targetWeightPct, priceHint);
  }

  qty = Math.floor(toNum(qty, 0));
  if (!qty || qty <= 0) { reject(symbol, "QTY_NONPOSITIVE", action); continue; }

  const effectiveAction = a.__normalized_action || action;
  const side = effectiveAction === "OPEN" || effectiveAction === "INCREASE" ? "BUY" : "SELL";
  const orderType = normalizeOrderType(a.entryPlan?.orderType ?? a.orderType);
  const buyPx = orderType === "LIMIT" ? limitPx : priceHint;
  const notionalPx = buyPx ?? priceHint;
  if (!notionalPx || notionalPx <= 0) { reject(symbol, "NO_PRICE"); continue; }

  if (side === "BUY" && limits.killSwitchActive) {
    reject(symbol, "KILL_SWITCH_BUY_BLOCKED");
    continue;
  }
  if (side === "BUY" && limits.requireLimitBuys && orderType !== "LIMIT") {
    reject(symbol, "BUY_REQUIRES_LIMIT");
    continue;
  }
  if (side === "SELL" && currentQty <= 0) {
    reject(symbol, "SELL_WITHOUT_POSITION");
    continue;
  }
  if (side === "SELL" && qty > currentQty) {
    warnings.push(`ORDER_RESIZED:SELL_POSITION_CAP:${symbol}:from=${qty}:to=${currentQty}`);
    qty = Math.floor(currentQty);
  }

  const h1Age = actionDataAge(a, ["Data_Age_H1_Hours", "dataAgeH1Hours", "data_age_h1_hours"]);
  const d1Age = actionDataAge(a, ["Data_Age_D1_Hours", "dataAgeD1Hours", "data_age_d1_hours"]);
  const spreadPct = actionDataAge(a, ["SpreadPct", "spreadPct", "spread_pct"]);
  const flags = actionFlagText(a).toUpperCase();
  const liquidityStatus = String(a?.liquidity?.status || "").trim().toUpperCase();
  const contractResolved = a?.liquidity?.contractResolved;
  const orderToVolumePct = toNumOrNull(a?.liquidity?.estimatedOrderToVolumePct);
  if (side === "BUY" && h1Age !== null && h1Age > limits.maxH1AgeHours) { reject(symbol, "STALE_H1", String(h1Age)); continue; }
  if (side === "BUY" && d1Age !== null && d1Age > limits.maxD1AgeHours) { reject(symbol, "STALE_D1", String(d1Age)); continue; }
  if (side === "BUY" && flags.includes("STALE_YF")) { reject(symbol, "STALE_YF"); continue; }
  if (side === "BUY" && ["UNKNOWN", "STRESS"].includes(liquidityStatus)) { reject(symbol, `LIQUIDITY_${liquidityStatus}`); continue; }
  if (side === "BUY" && contractResolved !== true) { reject(symbol, "IBKR_CONTRACT_UNRESOLVED"); continue; }
  if (side === "BUY" && ["LIQUIDITY_UNKNOWN", "LIQUIDITY_STRESS", "IBKR_CONTRACT_UNRESOLVED", "STALE_QUOTE", "PRICE_DIVERGENCE"].some((code) => flags.includes(code))) {
    reject(symbol, "LIQUIDITY_GATE", flags);
    continue;
  }
  // A null spread is tolerated only when the preflight vouched for the name's
  // liquidity (SPREAD_UNQUOTED) and the status resolved to OK. BUYs are LIMIT-only.
  const spreadUnquotedOk = flags.includes("SPREAD_UNQUOTED") && liquidityStatus === "OK";
  if (side === "BUY" && spreadPct === null && !spreadUnquotedOk) { reject(symbol, "LIQUIDITY_UNKNOWN", "spread"); continue; }
  if (side === "BUY" && spreadPct !== null && spreadPct > limits.maxSpreadPct) { reject(symbol, "SPREAD_TOO_WIDE", String(spreadPct)); continue; }

  const grossNotional = qty * notionalPx;
  const expectedFeesEUR = grossNotional * limits.defaultFeeBps / 10000.0;
  const postSymbolValue = Math.max(0, (posMarketValue[symbol] || 0) + (side === "BUY" ? grossNotional : -grossNotional));
  const postSymbolPct = portfolioValue > 0 ? (postSymbolValue / portfolioValue) * 100 : 0;
  const sector = clampText(a.sector ?? a.Sector ?? posSector[symbol] ?? "UNKNOWN", 128) || "UNKNOWN";
  const postSectorValue = Math.max(0, (sectorValue[sector] || 0) + (side === "BUY" ? grossNotional : -grossNotional));
  const postSectorPct = portfolioValue > 0 ? (postSectorValue / portfolioValue) * 100 : 0;
  const orderValuePct = portfolioValue > 0 ? (grossNotional / portfolioValue) * 100 : 0;

  // Plancher de ticket : rejette les micro-ordres d'achat manges par les frais fixes.
  if (side === "BUY" && grossNotional < limits.minOrderValueEUR) { reject(symbol, "MIN_ORDER_VALUE_EUR", `${grossNotional.toFixed(0)}<${limits.minOrderValueEUR}`); continue; }
  // Plafond du nombre de lignes : rejette une NOUVELLE ouverture au-dela du max (concentration).
  const isNewOpen = side === "BUY" && (action === "OPEN" || currentQty <= 0);
  if (isNewOpen && openPositionsCount >= limits.maxOpenPositions) { reject(symbol, "MAX_OPEN_POSITIONS", `${openPositionsCount}>=${limits.maxOpenPositions}`); continue; }
  if (side === "BUY" && postSymbolPct > limits.maxPosPct) { reject(symbol, "MAX_POSITION_PCT", postSymbolPct.toFixed(2)); continue; }
  if (side === "BUY" && sector !== "UNKNOWN" && postSectorPct > limits.maxSectorPct) { reject(symbol, "MAX_SECTOR_PCT", `${sector}:${postSectorPct.toFixed(2)}`); continue; }
  if (side === "BUY" && orderValuePct > limits.maxOrderValuePct) { reject(symbol, "MAX_ORDER_VALUE_PCT", orderValuePct.toFixed(2)); continue; }

  orders.push({
    symbol,
    action: effectiveAction,
    side,
    quantity: qty,
    assetClass,
    sector,
    isin: clampText(a.isin ?? a.ISIN ?? "", 64) || null,
    orderType,
    limitPrice: orderType === "LIMIT" ? limitPx : null,
    priceHint: notionalPx,
    estNotionalEUR: Math.round(grossNotional * 100) / 100,
    expectedFeesEUR: Math.round(expectedFeesEUR * 100) / 100,
    riskCheckPassed: true,
    riskChecks: {
      postSymbolPct,
      postSectorPct,
      orderValuePct,
      h1Age,
      d1Age,
      spreadPct,
      liquidityStatus,
      contractResolved,
      orderToVolumePct,
      dataFlags: flags,
    },
  });
}

let availableCash = cashEUR;
for (const o of orders) {
  if (o.side !== "SELL") continue;
  const sellPx = (normalizeOrderType(o.orderType) === "LIMIT" ? toNumOrNull(o.limitPrice) : null) ?? toNumOrNull(posLast[o.symbol]) ?? toNumOrNull(o.priceHint) ?? 0;
  availableCash += toNum(o.quantity, 0) * sellPx;
}

const cashSafeOrders = [];
for (const o of orders) {
  if (o.side === "SELL") {
    cashSafeOrders.push(o);
    continue;
  }

  const buyPx = (normalizeOrderType(o.orderType) === "LIMIT" ? toNumOrNull(o.limitPrice) : null) ?? toNumOrNull(o.priceHint) ?? toNumOrNull(posLast[o.symbol]);
  if (!buyPx || buyPx <= 0) {
    reject(o.symbol, "NO_BUY_PRICE");
    continue;
  }

  const requestedQty = toNum(o.quantity, 0);
  const affordableQty = Math.floor((availableCash + 1e-9) / (buyPx * (1 + limits.defaultFeeBps / 10000.0)));
  if (affordableQty <= 0) {
    reject(o.symbol, "INSUFFICIENT_CASH", `need=${(requestedQty * buyPx).toFixed(2)}:avail=${availableCash.toFixed(2)}`);
    continue;
  }
  if (affordableQty < requestedQty) {
    warnings.push(`ORDER_RESIZED:CASH_CAP:${o.symbol}:from=${requestedQty}:to=${affordableQty}`);
    o.quantity = affordableQty;
    o.estNotionalEUR = Math.round(affordableQty * buyPx * 100) / 100;
    o.expectedFeesEUR = Math.round((affordableQty * buyPx * limits.defaultFeeBps / 10000.0) * 100) / 100;
  }
  availableCash -= toNum(o.estNotionalEUR, 0) + toNum(o.expectedFeesEUR, 0);
  cashSafeOrders.push(o);
}

orders.length = 0;
orders.push(...cashSafeOrders);

const decision = orders.length ? "TRADE" : "NO_TRADE";
if (agentDecision?._parseStatus && !String(agentDecision._parseStatus).startsWith("OK")) {
  warnings.push(`AGENT_DECISION_PARSE:${agentDecision._parseStatus}`);
}

const ctx = {
  meta: input.meta ?? transfer_pack.meta ?? {},
  config: configRaw,
  run: { runId, timestampParis: ts, model },
  portfolioSummary,
  safetyLimits: limits,
};

return [{
  json: {
    decision,
    commentary: `Decision: ${decision} | Orders: ${orders.length} | Actions: ${(agentDecision.actions || []).length} | Rejects: ${rejects.length}`,
    agentDecision,
    orders,
    metrics: {
      rejects: rejects.length,
      availableCashAfterChecksEUR: Math.round(availableCash * 100) / 100,
    },
    warnings,
    ctx,
    portfolioSummary,
    transfer_pack,
    db_path: final_db_path,
  },
}];

function normalizeDbPath(v) {
  const s = String(v ?? "").trim().replace(/\\/g, "/");
  return s.replace("/local-files/", "/files/");
}

function toNum(v, dflt = null) {
  const n = Number(v);
  return Number.isFinite(n) ? n : dflt;
}

function pick(row, ...keys) {
  for (const key of keys) {
    const v = row?.[key];
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return null;
}

function clampText(v, max = 0) {
  const s = String(v ?? "").replace(/\s+/g, " ").trim();
  return max > 0 ? s.slice(0, max) : s;
}

function mapActionToSignal(action) {
  const a = String(action || "").toUpperCase();
  if (["OPEN", "INCREASE", "BUY"].includes(a)) return "BUY";
  if (["DECREASE", "CLOSE", "SELL"].includes(a)) return "SELL";
  if (a === "WATCH") return "WATCH";
  if (a === "HOLD") return "HOLD";
  if (a === "PROPOSE_OPEN") return "PROPOSE_OPEN";
  if (a === "PROPOSE_CLOSE") return "PROPOSE_CLOSE";
  return "NEUTRAL";
}

function normalizeOrderType(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (s === "LMT" || s === "LIMIT") return "LIMIT";
  if (s === "MKT" || s === "MARKET") return "MARKET";
  return s || "MARKET";
}

function extractSymbolFromText(text) {
  const m = String(text || "").toUpperCase().match(/\bFX:[A-Z]{6}\b|\b[A-Z0-9]{1,10}(?:\.[A-Z]{1,4})?\b/);
  return m ? m[0] : "GLOBAL";
}

function roundTo(v, digits = 2) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 0;
  const factor = 10 ** digits;
  return Math.round(n * factor) / factor;
}

function normalizeSymbol(v) {
  return String(v ?? "").trim();
}

function orderLedgerId(order, runId, index) {
  return String(order?.orderId || order?.order_id || order?.clientOrderId || `ORD_${runId}_${index}`).trim();
}

function brokerOrderId(order) {
  if (order?.brokerOrderId) return order.brokerOrderId;
  const raw = order?.ibkrResponse?.ibkr_response || order?.ibkrResponse?.details || order?.ibkrResponse;
  if (Array.isArray(raw) && raw.length > 0) {
    return raw[0]?.order_id || raw[0]?.orderId || raw[0]?.id || null;
  }
  return raw?.order_id || raw?.orderId || raw?.id || null;
}

function orderStatus(order) {
  const ibkr = String(order?.ibkrStatus || "").toLowerCase();
  if (ibkr === "submitted" || ibkr === "submitted_after_confirmation") return "SUBMITTED";
  if (ibkr === "filled" || ibkr === "executed") return "FILLED";
  if (ibkr === "dry_run") return "PLANNED";
  if (ibkr === "error" || ibkr === "not_sent") return "REJECTED";
  return "PLANNED";
}

function orderHasFillLikeEffect(order) {
  const ibkr = String(order?.ibkrStatus || "").toLowerCase();
  const broker = String(order?.broker || "").toUpperCase();
  const status = String(order?.status || order?.orderStatus || order?.executionStatus || "").toUpperCase();
  const explicitFill = Boolean(order?.ibkrFill || order?.fill || order?.execution || order?.brokerExecutionId);
  if (ibkr === "filled" || ibkr === "executed") return true;
  if (status === "FILLED" || status === "EXECUTED") return true;
  if (broker === "SIM" && ["SIM_FILLED", "SIMULATED_FILLED", "DRY_RUN_FILLED"].includes(status)) return true;
  return explicitFill && !["REJECTED", "BROKER_ERROR", "ERROR", "SUBMITTED", "PENDING", "PLANNED"].includes(status);
}

function rawFill(order) {
  return order?.ibkrFill || order?.fill || order?.execution || order?.ibkrExecution || {};
}

function pickWithKey(row, ...keys) {
  for (const key of keys) {
    const value = row?.[key];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return { key, value };
    }
  }
  return { key: "", value: null };
}

function extractFillTimestamp(order, fallbackTs) {
  const raw = rawFill(order);
  const picked = pickWithKey(
    raw,
    "filled_at",
    "filledAt",
    "trade_time",
    "tradeTime",
    "execution_time",
    "executionTime",
    "time",
    "timestamp"
  ).value;
  if (!picked) return fallbackTs;
  const dt = new Date(picked);
  return Number.isNaN(dt.getTime()) ? fallbackTs : dt.toISOString();
}

function extractBrokerExecutionId(order) {
  const raw = rawFill(order);
  return clampText(
    pickWithKey(
      raw,
      "execution_id",
      "executionId",
      "execId",
      "trade_id",
      "tradeId",
      "id"
    ).value || order?.brokerExecutionId || order?.brokerOrderId || order?.clientOrderId || "",
    128
  ) || null;
}

function extractFillPrice(order, priceMap) {
  const raw = rawFill(order);
  const rawPrice = toNum(
    pickWithKey(raw, "price", "avgPrice", "avg_price", "fill_price", "fillPrice", "execution_price", "executionPrice").value,
    null
  );
  if (rawPrice !== null && rawPrice > 0) return rawPrice;
  const symbol = String(order?.symbol || "").trim();
  const orderType = normalizeOrderType(order?.orderType);
  if (orderType === "LIMIT") {
    const limitPrice = toNum(order?.limitPrice, null);
    if (limitPrice !== null && limitPrice > 0) return limitPrice;
  }
  const mappedPrice = toNum(priceMap[symbol], null);
  return (mappedPrice !== null && mappedPrice > 0) ? mappedPrice : 1.0;
}

function extractFillQty(order) {
  const raw = rawFill(order);
  const rawQty = toNum(
    pickWithKey(raw, "quantity", "qty", "shares", "size", "filledQuantity", "filled_quantity", "fill_size", "fillSize").value,
    null
  );
  if (rawQty !== null && rawQty > 0) return rawQty;
  return toNum(order?.quantity, 0) || 0;
}

function extractCommission(order) {
  const raw = rawFill(order);
  const picked = pickWithKey(
    raw,
    "commission",
    "ibCommission",
    "ib_commission",
    "commission_amount",
    "commissionAmount",
    "fees_eur",
    "fee"
  );
  const rawAmount = toNum(picked.value, null);
  const rawCcy = clampText(
    pickWithKey(
      raw,
      "commissionCurrency",
      "commission_currency",
      "commissionCcy",
      "ibCommissionCurrency",
      "feeCurrency",
      "currency"
    ).value || "",
    8
  ).toUpperCase();

  if (rawAmount !== null) {
    const sourceBase = picked.key ? `ibkr_${picked.key}` : "ibkr_commission";
    const source = rawCcy && rawCcy !== "EUR"
      ? `${sourceBase}_reported_${rawCcy}_assumed_eur`
      : (rawCcy ? sourceBase : `${sourceBase}_fallback_eur_no_ccy`);
    return {
      commissionAmount: Math.abs(rawAmount),
      commissionCcy: rawCcy || "EUR",
      commissionEUR: Math.abs(rawAmount),
      commissionSource: source,
    };
  }

  const expected = toNum(order?.actualFeesEUR ?? order?.expectedFeesEUR ?? order?.feesEUR ?? order?.fees_eur, 0) || 0;
  const ibkrStatus = String(order?.ibkrStatus || "").toLowerCase();
  return {
    commissionAmount: Math.abs(expected),
    commissionCcy: "EUR",
    commissionEUR: Math.abs(expected),
    commissionSource: ibkrStatus === "dry_run" ? "simulated_bps" : "ibkr_commission_missing",
  };
}

function inferRiskStatus(cashPct, cashEUR) {
  if (Number.isFinite(cashEUR) && cashEUR < -0.01) return "RISK_OFF";
  if (Number.isFinite(cashPct) && cashPct >= 0.8) return "DEFENSIVE";
  if (Number.isFinite(cashPct) && cashPct <= 0.1) return "RISK_ON";
  return "BALANCED";
}

function buildSnapshotsFromPortfolio(portfolioSummary, orders, priceMap, ts, meta) {
  const positionsIn = Array.isArray(portfolioSummary?.positions) ? portfolioSummary.positions : [];
  const positionsValueInput = positionsIn.reduce((sum, row) => {
    const marketValue = toNum(pick(row, "MarketValue", "marketValue", "value"), null);
    if (marketValue !== null) return sum + marketValue;
    return sum + (toNum(pick(row, "Quantity", "quantity", "qty"), 0) * toNum(pick(row, "LastPrice", "lastPrice", "price"), 0));
  }, 0);
  const summaryCash = toNum(portfolioSummary?.cashEUR, null);
  const summaryTotal = toNum(portfolioSummary?.totalPortfolioValueEUR, null);
  let startCash = summaryCash;
  if (
    summaryTotal !== null
    && Number.isFinite(positionsValueInput)
    && Math.abs(((summaryCash ?? 0) + positionsValueInput) - summaryTotal) > 0.01
  ) {
    const reconciledCash = summaryTotal - positionsValueInput;
    if (Number.isFinite(reconciledCash)) startCash = reconciledCash;
  }
  if (!Number.isFinite(startCash)) startCash = 0;
  const posMap = new Map();

  for (const row of positionsIn) {
    const symbol = normalizeSymbol(pick(row, "Symbol", "symbol"));
    const qty = toNum(pick(row, "Quantity", "quantity", "qty"), 0);
    if (!symbol || qty <= 0) continue;
    posMap.set(symbol, {
      symbol,
      qty,
      avgCost: toNum(pick(row, "AvgPrice", "avgPrice"), toNum(pick(row, "LastPrice", "lastPrice", "price"), 0) || 0),
      lastPrice: toNum(pick(row, "LastPrice", "lastPrice", "price"), toNum(pick(row, "AvgPrice", "avgPrice"), 0) || 0),
      assetClass: String(pick(row, "AssetClass", "assetClass", "asset_class") || "EQUITY").trim().toUpperCase() || "EQUITY",
      sector: clampText(pick(row, "Sector", "sector") || "UNKNOWN", 128) || "UNKNOWN",
    });
  }

  let cashEUR = startCash;
  let runFeesEUR = 0;
  for (const order of orders || []) {
    const symbol = normalizeSymbol(order?.symbol);
    const side = String(order?.side || "").trim().toUpperCase();
    const qty = toNum(order?.quantity, 0);
    const orderType = normalizeOrderType(order?.orderType);
    const price =
      (orderType === "LIMIT" ? toNum(order?.limitPrice, null) : null) ??
      toNum(priceMap[symbol], null);

    if (!symbol || qty <= 0 || !Number.isFinite(price) || price <= 0) continue;
    const feesEUR = extractCommission(order).commissionEUR;
    runFeesEUR += Math.max(0, feesEUR);

    if (side === "BUY") {
      const current = posMap.get(symbol) || {
        symbol,
        qty: 0,
        avgCost: price,
        lastPrice: price,
        assetClass: String(order?.assetClass || "EQUITY").trim().toUpperCase() || "EQUITY",
        sector: "UNKNOWN",
      };
      const newQty = current.qty + qty;
      current.avgCost = newQty > 0 ? (((current.qty * current.avgCost) + (qty * price)) / newQty) : price;
      current.qty = newQty;
      current.lastPrice = toNum(priceMap[symbol], price);
      posMap.set(symbol, current);
      cashEUR -= (qty * price) + feesEUR;
      continue;
    }

    if (side === "SELL") {
      const current = posMap.get(symbol);
      if (!current) continue;
      const execQty = Math.min(qty, current.qty);
      if (execQty <= 0) continue;
      current.qty -= execQty;
      current.lastPrice = toNum(priceMap[symbol], price);
      cashEUR += (execQty * price) - feesEUR;
      if (current.qty <= 1e-9) posMap.delete(symbol);
      else posMap.set(symbol, current);
    }
  }

  const positions = [];
  const sectorTotals = {};
  let equityEUR = 0;

  for (const current of posMap.values()) {
    const lastPrice = toNum(priceMap[current.symbol], current.lastPrice ?? current.avgCost ?? 0);
    const marketValue = current.qty * lastPrice;
    const unrealizedPnL = (lastPrice - current.avgCost) * current.qty;
    equityEUR += marketValue;
    const sector = current.sector || "UNKNOWN";
    sectorTotals[sector] = (sectorTotals[sector] || 0) + marketValue;
    positions.push({
      symbol: current.symbol,
      ts,
      qty: current.qty,
      avg_cost: roundTo(current.avgCost, 8),
      last_price: roundTo(lastPrice, 8),
      market_value_eur: roundTo(marketValue, 2),
      unrealized_pnl_eur: roundTo(unrealizedPnL, 2),
      weight_pct: 0,
    });
  }

  const totalValueEUR = cashEUR + equityEUR;
  for (const position of positions) {
    position.weight_pct = totalValueEUR > 0 ? position.market_value_eur / totalValueEUR : 0;
  }

  const initialCapitalEUR = toNum(meta?.initialCapitalEUR, 10000);
  const cumFeesEUR = toNum(meta?.cumFeesEUR, 0) + runFeesEUR;
  const cumAiCostEUR = toNum(meta?.cumAiCostEUR, 0);
  const totalPnLEUR = totalValueEUR - initialCapitalEUR;
  const roi = initialCapitalEUR > 0 ? (totalPnLEUR / initialCapitalEUR) : 0;
  const cashPct = totalValueEUR > 0 ? (cashEUR / totalValueEUR) : 0;
  const top1PosPct = positions.length
    ? Math.max(...positions.map((p) => Number(p.market_value_eur) || 0)) / (totalValueEUR || 1)
    : 0;
  const top1SectorPct = Object.keys(sectorTotals).length
    ? Math.max(...Object.values(sectorTotals)) / (totalValueEUR || 1)
    : 0;
  const riskStatus = inferRiskStatus(cashPct, cashEUR);

  return {
    positions,
    portfolio: {
      ts,
      cash_eur: roundTo(cashEUR, 2),
      equity_eur: roundTo(equityEUR, 2),
      total_value_eur: roundTo(totalValueEUR, 2),
      cum_fees_eur: roundTo(cumFeesEUR, 2),
      cum_ai_cost_eur: roundTo(cumAiCostEUR, 2),
      trades_this_run: orders.length,
      total_pnl_eur: roundTo(totalPnLEUR, 2),
      roi,
      drawdown_pct: 0,
      meta_json: {
        source: "node8_portfolio_summary",
        start_cash_eur: roundTo(startCash, 2),
      },
    },
    risk: {
      ts,
      cash_pct: cashPct,
      top1_pos_pct: top1PosPct,
      top1_sector_pct: top1SectorPct,
      var95_est_eur: roundTo(equityEUR * 0.015 * 1.65, 2),
      positions_count: positions.length,
      risk_status: riskStatus,
      limits_json: {
        source: "node8_portfolio_summary",
      },
    },
  };
}

const input = $json || {};
const transferPack = input.transfer_pack || {};
const ctx = input.ctx || {};
const runCtx = {
  ...(ctx.run || {}),
  ...(input.run || {}),
  ...(transferPack.run || {}),
};
const meta = input.meta || ctx.meta || transferPack.meta || {};
const agentDecision = input.agentDecision || {};
const ordersIn = Array.isArray(input.orders) ? input.orders : [];
const modelProposals = Array.isArray(input.modelProposals)
  ? input.modelProposals
  : (Array.isArray(agentDecision?.consensus?.modelProposals) ? agentDecision.consensus.modelProposals : []);
const consensusVotes = Array.isArray(input.consensusVotes)
  ? input.consensusVotes
  : (Array.isArray(agentDecision?.consensus?.votes) ? agentDecision.consensus.votes : []);
const consensusDecisions = Array.isArray(input.consensusDecisions)
  ? input.consensusDecisions
  : (Array.isArray(agentDecision?.consensus?.decisions) ? agentDecision.consensus.decisions : []);
const fillEffectOrders = ordersIn.filter(orderHasFillLikeEffect);
const warnings = Array.isArray(input.warnings) ? input.warnings : [];
const ts_end = new Date().toISOString();
const run_id = runCtx.runId || `RUN_${Date.now()}`;
const db_path = normalizeDbPath(input.db_path || runCtx.db_path || "");

// IMPORTANT: portfolio is in ctx (from node 7)
const portfolioSummary = input.portfolioSummary || ctx.portfolioSummary || { positions: [] };

// --- PRICE MAP ---
const priceMap = {};
if (Array.isArray(portfolioSummary.positions)) {
  portfolioSummary.positions.forEach((p) => {
    const sym = String(pick(p, "Symbol", "symbol") ?? "").trim();
    const px = Number(pick(p, "LastPrice", "lastPrice", "price"));
    if (sym && Number.isFinite(px) && px > 0) priceMap[sym] = px;
  });
}

const instrumentMap = new Map();
if (Array.isArray(portfolioSummary.positions)) {
  portfolioSummary.positions.forEach((p) => {
    const symbol = normalizeSymbol(pick(p, "Symbol", "symbol"));
    if (!symbol || symbol === "CASH_EUR" || symbol === "__META__") return;
    instrumentMap.set(symbol, {
      symbol,
      name: clampText(pick(p, "Name", "name") || symbol, 256),
      asset_class: clampText(pick(p, "AssetClass", "assetClass", "asset_class") || "Equity", 64),
      sector: clampText(pick(p, "Sector", "sector") || "", 128) || null,
      industry: clampText(pick(p, "Industry", "industry") || "", 128) || null,
      isin: clampText(pick(p, "ISIN", "isin") || "", 64) || null,
    });
  });
}

// complete with limit prices from actions/orders
if (Array.isArray(agentDecision.actions)) {
  agentDecision.actions.forEach((a) => {
    const sym = String(a.symbol_internal || a.symbol || "").trim();
    const lp = Number(a.entryPlan?.limitPrice);
    if (sym && !(sym in priceMap) && Number.isFinite(lp) && lp > 0) priceMap[sym] = lp;
    if (sym && !instrumentMap.has(sym)) {
      instrumentMap.set(sym, {
        symbol: sym,
        name: sym,
        asset_class: clampText(a.assetClass || "Equity", 64),
        sector: null,
        industry: null,
        isin: null,
      });
    }
  });
}

ordersIn.forEach((o) => {
  const sym = String(o.symbol || "").trim();
  const lp = Number(o.limitPrice);
  if (sym && !(sym in priceMap) && Number.isFinite(lp) && lp > 0) priceMap[sym] = lp;
});

const ai_signals = [];
if (Array.isArray(agentDecision.actions)) {
  agentDecision.actions.forEach((a, i) => {
    const symbol = String(a.symbol_internal || a.symbol || "").trim();
    if (!symbol || symbol === "CASH_EUR") return;
    const confidence = toNum(a.confidence, null);
    const signal = mapActionToSignal(a.action);
    const horizonDays = toNum(a.horizonDays, null);
    ai_signals.push({
      signal_id: `SIG_${run_id}_${i}`,
      ts: ts_end,
      symbol,
      signal,
      confidence: confidence == null ? null : Math.max(0, Math.min(100, Math.round(confidence))),
      horizon: Number.isFinite(horizonDays) ? `D${Math.max(1, Math.round(horizonDays))}` : null,
      entry_zone: clampText(a.entryPlan?.orderType || "", 32) || null,
      stop_loss: toNum(a.riskPlan?.stopLossPct, null),
      take_profit: toNum(a.riskPlan?.takeProfitPct, null),
      risk_score: confidence == null ? null : Math.max(0, Math.min(100, 100 - Math.round(confidence))),
      catalyst: null,
      rationale: clampText(a.rationale, 2048) || null,
      payload_json: a,
    });
  });
}

const alerts = [];
warnings.forEach((w, i) => {
  const msg = clampText(w, 2048);
  if (!msg) return;
  alerts.push({
    alert_id: `ALT_${run_id}_${i}`,
    ts: ts_end,
    severity: "WARN",
    category: "AGENT",
    symbol: extractSymbolFromText(msg),
    message: msg,
    code: "AGENT_WARNING",
    payload_json: { warning: String(w) },
  });
});

if (String(input.decision || "").toUpperCase() === "NO_TRADE" && warnings.length === 0) {
  alerts.push({
    alert_id: `ALT_${run_id}_NOTRADE`,
    ts: ts_end,
    severity: "INFO",
    category: "EXECUTION",
    symbol: "GLOBAL",
    message: "No executable orders for this run",
    code: "NO_TRADE",
    payload_json: { decision: input.decision || "NO_TRADE" },
  });
}

const fillRecords = fillEffectOrders.map((o, i) => {
  const sym = String(o.symbol || "").trim();
  const order_id = orderLedgerId(o, run_id, i);
  const fee = extractCommission(o);
  const px = extractFillPrice(o, priceMap);
  const qty = extractFillQty(o);
  const brokerExecutionId = extractBrokerExecutionId(o);
  const tsFill = extractFillTimestamp(o, ts_end);
  const fillId = brokerExecutionId
    ? `FIL_${run_id}_${brokerExecutionId}`
    : `FIL_${run_id}_${i}`;

  return {
    fill_id: fillId,
    order_id,
    symbol: sym,
    side: o.side,
    qty,
    price: (Number.isFinite(px) && px > 0) ? px : 1.0,
    ts_fill: tsFill,
    fees_eur: fee.commissionEUR,
    fee_amount: fee.commissionAmount,
    fee_ccy: fee.commissionCcy,
    fee_source: fee.commissionSource,
    broker: o.broker || (o.ibkrStatus ? "IBKR" : "SIM"),
    broker_execution_id: brokerExecutionId,
    slippage_bps: toNum(o.slippageBps ?? o.slippage_bps, null),
    liquidity: clampText(o.liquidity || "UNKNOWN", 32),
    raw_fill_json: {
      source: o.ibkrStatus === "dry_run" ? "simulated_sandbox" : "confirmed_or_imported",
      clientOrderId: o.clientOrderId || null,
      ibkrStatus: o.ibkrStatus || null,
      ibkrResponse: o.ibkrResponse || null,
      ibkrFill: rawFill(o) || null,
    },
  };
});

const fillCostRecords = fillRecords.map((f) => ({
  fill_id: f.fill_id,
  order_id: f.order_id,
  symbol: f.symbol,
  pair: f.symbol,
  broker: f.broker,
  broker_execution_id: f.broker_execution_id,
  commission_amount: f.fee_amount,
  commission_ccy: f.fee_ccy,
  commission_eur: f.fees_eur,
  commission_source: f.fee_source,
  raw_json: f.raw_fill_json,
  recorded_at: f.ts_fill,
}));

const snapshots = buildSnapshotsFromPortfolio(portfolioSummary, fillEffectOrders, priceMap, ts_end, meta);

const bundle = {
  run: {
    run_id,
    ts_start: runCtx.timestampParis || ts_end,
    ts_end,
    tz: "Europe/Paris",
    strategy_version: runCtx.strategyVersion || runCtx.strategy_version || null,
    config_version: runCtx.configVersion || runCtx.config_version || null,
    prompt_version: runCtx.promptVersion || runCtx.prompt_version || null,
    model: runCtx.model || "UNKNOWN",
    n8n_execution_id: runCtx.executionId || runCtx.n8nExecutionId || runCtx.n8n_execution_id || null,
    db_path: db_path || null,
    decision_summary: input.decision || "NO_TRADE",
    data_ok_for_trading: true,
    agent_output_json: agentDecision,
    warnings_json: warnings,
  },
  orders: ordersIn.map((o, i) => ({
    order_id: orderLedgerId(o, run_id, i),
    symbol: o.symbol,
    side: o.side,
    order_type: normalizeOrderType(o.orderType),
    qty: o.quantity,
    limit_price: o.limitPrice ?? null,
    status: orderStatus(o),
    broker: o.broker || (o.ibkrStatus ? "IBKR" : "SIM"),
    broker_order_id: brokerOrderId(o),
    reason: o.ibkrError || o.reason || null,
    rationale_json: {
      action: o.action,
      assetClass: o.assetClass,
      clientOrderId: o.clientOrderId || null,
      ibkrStatus: o.ibkrStatus || null,
      ibkrResponse: o.ibkrResponse || null,
      ibkrError: o.ibkrError || null,
      expectedFeesEUR: o.expectedFeesEUR || 0,
      riskChecks: o.riskChecks || null,
    },
  })),
  fills: fillRecords,
  fill_costs: fillCostRecords,
  cash_ledger: [],
  instruments: Array.from(instrumentMap.values()),
  market_prices: Object.entries(priceMap).map(([sym, px]) => ({ symbol: sym, close: px })),
  ai_signals,
  model_proposals: modelProposals,
  consensus_votes: consensusVotes,
  consensus_decisions: consensusDecisions,
  alerts,
  snapshots,
};

return [{
  json: {
    run_id,
    db_path,
    bundle,
    summary: {
      decision: input.decision,
      orders: ordersIn.length,
      fills: bundle.fills.length,
      ai_signals: ai_signals.length,
      model_proposals: modelProposals.length,
      consensus_votes: consensusVotes.length,
      consensus_decisions: consensusDecisions.length,
      alerts: alerts.length,
    }
  }
}];

