  row.regular_market_time = quoteTime;
  row.market_state = ibkrHasFreshPrice ? "IBKR_SNAPSHOT" : (ibkrHasHistoryPrice ? "IBKR_HISTORY" : (quote.marketState || row.market_state || null));

  row.gates = gates.size ? Array.from(gates).sort().join("|") : "OK";
  row.spread_pct = spreadPct;
  row.volume = volume;
  row.liquidity = {
    status: gates.has("LIQUIDITY_STRESS") ? "STRESS" : (gates.has("LIQUIDITY_UNKNOWN") ? "UNKNOWN" : "OK"),
    conid,
    contractResolved: conid !== null,
    quoteSource: row.quote_source,
    quoteTime,
    quoteAgeMinutes: quoteAgeMinutes === null ? null : Math.round(quoteAgeMinutes * 10) / 10,
    marketState: row.market_state,
    price,
    bid: ibkrHasFreshPrice ? ibkrBid : num(quote.bid),
    ask: ibkrHasFreshPrice ? ibkrAsk : num(quote.ask),
    spreadPct,
    spreadObserved: spreadPct !== null,
    spreadUnquoted: gates.has("SPREAD_UNQUOTED"),
    volume,
    estimatedTargetWeightPct: defaultWeightPct,
    estimatedTargetQty: targetQty,
    estimatedOrderToVolumePct: orderVolumePct === null ? null : Math.round(orderVolumePct * 10000) / 10000,
    entryQuoteDivergencePct: priceDivergencePct === null ? null : Math.round(priceDivergencePct * 10000) / 10000,
    originalMatrixEntry: entry,
    ibkrSnapshotPrice: ibkrPrice,
    ibkrSnapshotAttempts,
    ibkrHistoryPrice,
    ibkrHistoryTime: ibkrHistory?.time || null,
    ibkrHistoryBar: ibkrHistory ? { period: ibkrHistory.period, barSize: ibkrHistory.barSize } : null,
    readOnlyChecks: ["yfinance_quote", "ibkr_contract_resolution", "ibkr_market_snapshot", "ibkr_market_history"],
  };
}

pack.rows = rows;
pack.liquidityPreflight = {
  generatedAt: new Date().toISOString(),
  candidateCount: candidates.length,
  contractResolved: conidMap.size,
  quoteCount: quotes.length,
  ibkrSnapshotCount: ibkrSnapshots.length,
  ibkrSnapshotPricedCount: ibkrSnapshots.filter(snapshotHasPrice).length,
  ibkrSnapshotAttempts,
  ibkrHistoryAttempts,
  ibkrHistoryPricedCount: ibkrHistoryMap.size,
  warnings: preflightWarnings,
  orderEndpointsCalled: false,
};

return [{ json: { ...input, opportunity_pack: pack } }];

// AG1 V4 - Build 2/3 consensus from GPT, Grok and Claude proposals.
// Mode: Run Once for All Items.

function isObj(x) { return x && typeof x === "object" && !Array.isArray(x); }
function toNumOrNull(x) {
  const n = Number(x);
  return Number.isFinite(n) ? n : null;
}
function clampText(v, max = 0) {
  const s = String(v ?? "").replace(/\s+/g, " ").trim();
  return max > 0 ? s.slice(0, max) : s;
}
function normSymbol(v) { return String(v ?? "").trim().toUpperCase(); }
function normAction(v) { return String(v ?? "").trim().toUpperCase(); }
function deepClone(obj) {
  try { return JSON.parse(JSON.stringify(obj)); } catch { return obj; }
}
function safeArray(v) { return Array.isArray(v) ? v : []; }

function normAssetClass(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (!s || ["EQUITY", "STOCK", "STK"].includes(s)) return "EQUITY";
  if (s === "ETF") return "ETF";
  if (s === "CRYPTO") return "CRYPTO";
  return s;
}

function isFxSymbol(action) {
  const symbol = normSymbol(action?.symbol_internal || action?.symbol);
  const yahoo = String(action?.symbol_yahoo || "").trim().toUpperCase();
  const ac = normAssetClass(action?.assetClass ?? action?.AssetClass);
  return symbol.startsWith("FX:") || yahoo.endsWith("=X") || ["FX", "FOREX", "CURRENCY"].includes(ac);
}

function normalizeIntent(actionName) {
  const a = normAction(actionName);
  if (["OPEN", "INCREASE", "BUY"].includes(a)) return "BUY";
  if (["DECREASE", "CLOSE", "SELL"].includes(a)) return "SELL";
  if (a === "HOLD") return "HOLD";
  if (a === "WATCH") return "WATCH";
  return "UNKNOWN";
}

function sideForIntent(intent) {
  if (intent === "BUY") return "BUY";
  if (intent === "SELL") return "SELL";
  return null;
}

function normalizeOrderType(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (["LMT", "LIMIT"].includes(s)) return "LIMIT";
  if (["MKT", "MARKET"].includes(s)) return "MARKET";
  return s || "MARKET";
}

function pickLimitPrice(action) {
  return toNumOrNull(action?.entryPlan?.limitPrice ?? action?.limitPrice);
}

function pickTargetQty(action) {
  return toNumOrNull(action?.targetQty ?? action?.target_qty);
}

function pickTargetWeightPct(action) {
  return toNumOrNull(action?.targetWeightPct ?? action?.target_weight_pct);
}

function pickConfidence(action) {
  const n = toNumOrNull(action?.confidence);
  if (n === null) return null;
  return Math.max(0, Math.min(100, n));
}

function median(values) {
  const arr = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (!arr.length) return null;
  const mid = Math.floor(arr.length / 2);
  return arr.length % 2 ? arr[mid] : (arr[mid - 1] + arr[mid]) / 2;
}

function conservativeQty(values) {
  const arr = values.filter((x) => Number.isFinite(x) && x > 0);
  if (!arr.length) return null;
  return Math.floor(Math.min(...arr));
}

function conservativeWeight(values) {
  const arr = values.filter((x) => Number.isFinite(x) && x > 0);
  if (!arr.length) return null;
  return Math.min(...arr);
}

function inferModelKey(item, index) {
  const raw = String(
    item.model_key ||
    item.modelKey ||
    item.llm_model_key ||
    item.llmModelKey ||
    item.model ||
    item.modelName ||
    item.model_name ||
    ""
  ).trim().toLowerCase();
  if (raw.includes("grok") || raw.includes("xai")) return "grok41_reasoning";
  if (raw.includes("claude") || raw.includes("anthropic") || raw.includes("sonnet")) return "claude_sonnet46";
  if (raw.includes("gpt") || raw.includes("openai") || raw.includes("chatgpt")) return "chatgpt52";
  return ["chatgpt52", "grok41_reasoning", "claude_sonnet46"][index] || `model_${index + 1}`;
}

function modelDisplayKey(v) {
  return clampText(
    v?.modelId ||
    v?.model_id ||
    v?.modelName ||
    v?.model_name ||
    v?.model ||
    v?.modelKey ||
    v?.model_key ||
    "",
    128
  ) || "UNKNOWN_MODEL";
}

function extractDecision(item) {
  if (isObj(item.output) && Array.isArray(item.output.actions)) return item.output;
  if (isObj(item.agentDecision) && Array.isArray(item.agentDecision.actions)) return item.agentDecision;
  if (Array.isArray(item.output)) return { actions: item.output };
  return isObj(item.output) ? item.output : {};
}

function buildPortfolioSummary(context) {
  if (isObj(context.portfolioSummary)) return context.portfolioSummary;
  const pb = isObj(context.portfolioBrief) ? context.portfolioBrief : {};
  const summary = isObj(pb.summary) ? pb.summary : {};
  const cashEUR = toNumOrNull(pb.cash ?? summary.cash ?? summary.cashEUR) ?? 10000;
  const totalPortfolioValueEUR = toNumOrNull(pb.totalValue ?? summary.totalValue ?? summary.totalPortfolioValueEUR) ?? cashEUR;
  return {
    cashEUR,
    totalPortfolioValueEUR,
    marketValueEUR: toNumOrNull(pb.marketValue ?? summary.marketValue) ?? Math.max(0, totalPortfolioValueEUR - cashEUR),
    exposurePct: toNumOrNull(pb.exposurePct ?? summary.exposurePct) ?? 0,
    positions: safeArray(pb.positions),
  };
}

function buildPositionQtyMap(portfolioSummary) {
  const out = {};
  for (const p of safeArray(portfolioSummary.positions)) {
    const s = normSymbol(p?.symbol || p?.Symbol);
    if (!s || s === "CASH_EUR" || s === "__META__") continue;
    const qty = toNumOrNull(p?.quantity ?? p?.Quantity ?? p?.qty) ?? 0;
    out[s] = qty;
  }
  return out;
}

function pickPositionPrice(portfolioSummary, symbol) {
  const wanted = normSymbol(symbol);
  for (const p of safeArray(portfolioSummary.positions)) {
    const s = normSymbol(p?.symbol || p?.Symbol);
    if (s !== wanted) continue;
    const direct = toNumOrNull(
      p?.lastPrice ??
      p?.LastPrice ??
      p?.price ??
      p?.Price ??
      p?.marketPrice ??
      p?.MarketPrice
    );
    if (direct !== null && direct > 0) return direct;
    const qty = toNumOrNull(p?.quantity ?? p?.Quantity ?? p?.qty) ?? 0;
    const marketValue = toNumOrNull(
      p?.marketValue ??
      p?.MarketValue ??
      p?.market_value ??
      p?.MarketValueEUR ??
      p?.marketValueEUR ??
      p?.value
    );
    if (qty > 0 && marketValue !== null && marketValue > 0) return marketValue / qty;
  }
  return null;
}

function selectActionName(intent, votes, currentQty) {
  const counts = {};
  for (const v of votes) {
    counts[v.action] = (counts[v.action] || 0) + 1;
  }
  if (intent === "SELL") {
    if ((counts.CLOSE || 0) >= 2) return "CLOSE";
    return currentQty > 0 ? "DECREASE" : "CLOSE";
  }
  if (intent === "BUY") {
    if (currentQty > 0) return "INCREASE";
    if ((counts.INCREASE || 0) > (counts.OPEN || 0) && currentQty > 0) return "INCREASE";
    return "OPEN";
  }
  return intent;
}

function buildSelectedAction(group, posQtyMap, runId, opportunityMap, portfolioSummary, config) {
  const votes = group.votes;
  const representative = deepClone(votes[0].rawAction || {});
  const symbol = group.symbol;
  const intent = group.intent;
  const side = sideForIntent(intent);
  const currentQty = posQtyMap[symbol] || 0;
  const selectedAction = selectActionName(intent, votes, currentQty);
  const matrix = opportunityMap[symbol] || {};
  const maxPosPct = toNumOrNull(config?.max_pos_pct ?? config?.maxPositionPct) ?? 25;
  const votedWeight = conservativeWeight(votes.map((v) => v.targetWeightPct));
  const weight = Math.max(0, Math.min(maxPosPct, votedWeight ?? (intent === "BUY" ? 5 : 0)));
  const selectedLimit = toNumOrNull(matrix.entry) ?? (intent === "SELL" ? pickPositionPrice(portfolioSummary, symbol) : null);
  const totalValue = toNumOrNull(portfolioSummary.totalPortfolioValueEUR) ?? 0;
  let qty = selectedLimit && selectedLimit > 0 && totalValue > 0
    ? Math.floor((totalValue * weight / 100) / selectedLimit)
    : null;
  if (selectedAction === "CLOSE") qty = 0;
  if (selectedAction === "DECREASE" && qty !== null) qty = Math.min(currentQty, qty);
  const confidence = Math.round(median(votes.map((v) => v.confidence).filter((x) => x !== null)) ?? 50);
  const modelKeysCanonical = votes.map((v) => v.modelKey).sort();
  const modelKeys = votes.map(modelDisplayKey).sort();
  const consensusId = `CONS_${runId}_${symbol}_${intent}`;

  if (selectedAction === "DECREASE" && (votedWeight === null || qty === null)) {
    return {
      decision: {
        consensus_id: consensusId,
        symbol,
        intent,
        action: selectedAction,
        side,
        vote_count: votes.length,
        valid_model_count: group.validModelCount,
        model_keys: modelKeys.join(","),
        status: "REJECTED_MISSING_TARGET_WEIGHT",
        reason: "DECREASE requires a deterministic final target weight and reference price",
        selected_qty: null,
        selected_weight_pct: votedWeight,
        selected_limit_price: selectedLimit,
        confidence,
        payload_json: { votes, matrix },
      },
      action: null,
    };
  }

  const entryPlan = {
    orderType: side === "BUY" ? "LIMIT" : "MARKET",
    limitPrice: side === "BUY" ? selectedLimit : null,
    timeInForce: "DAY",
  };
  const stopPrice = toNumOrNull(matrix.stop);
  const takeProfitPrice = toNumOrNull(matrix.tp);
  const stopLossPct = selectedLimit && stopPrice ? ((stopPrice - selectedLimit) / selectedLimit) * 100 : null;
  const takeProfitPct = selectedLimit && takeProfitPrice ? ((takeProfitPrice - selectedLimit) / selectedLimit) * 100 : null;
  const maxLossEUR = qty && selectedLimit && stopPrice ? Math.max(0, qty * (selectedLimit - stopPrice)) : null;

  const action = {
    ...representative,
    symbol,
    symbol_internal: symbol,
    symbol_yahoo: matrix.symbol_yahoo || symbol,
    assetClass: normAssetClass(matrix.asset_class || representative.assetClass || representative.AssetClass),
    sector: matrix.sector || representative.sector || "UNKNOWN",
    action: selectedAction,
    signal: side,
    confidence,
    targetQty: qty,
    targetWeightPct: weight,
    entryPlan,
    priceHint: selectedLimit,
    riskPlan: { stopLossPct, takeProfitPct, maxLossEUR },
    Data_Age_H1_Hours: toNumOrNull(matrix.data_age_h1_hours),
    Data_Age_D1_Hours: toNumOrNull(matrix.data_age_d1_hours),
    SpreadPct: toNumOrNull(matrix.spread_pct),
    dataQualityFlags: matrix.gates || "",
    liquidity: matrix.liquidity || null,
    rationale: clampText(
      `AG1 V4 consensus ${votes.length}/3 (${modelKeys.join(", ")}): ${representative.rationale || ""}`,
      2048
    ),
    consensusMeta: {
      consensusId,
      runId,
      intent,
      voteCount: votes.length,
      validModelCount: group.validModelCount,
      modelKeys,
      modelKeysCanonical,
      modelIds: votes.map((v) => v.modelId).filter(Boolean).sort(),
      sizingRule: "deterministic_target_weight_to_final_quantity",
      priceRule: "pre_llm_fresh_entry",
    },
  };

  return {
    decision: {
      consensus_id: consensusId,
      symbol,
      intent,
      action: selectedAction,
      side,
      vote_count: votes.length,
      valid_model_count: group.validModelCount,
      model_keys: modelKeys.join(","),
      status: "CONSENSUS_APPROVED",
      reason: `Executable consensus ${votes.length}/3`,
      selected_qty: qty,
      selected_weight_pct: weight,
      selected_limit_price: selectedLimit,
      confidence,
      payload_json: { action, votes, matrix, modelKeysCanonical },
    },
    action,
  };
}

const items = $input.all().map((it) => it.json || {});
const context = items.find((it) => isObj(it.portfolioBrief) || isObj(it.opportunity_pack) || isObj(it.run)) || {};
const run = isObj(context.run) ? context.run : {};
const runId = String(run.runId || run.run_id || `RUN_${Date.now()}`);
const dbPath = String(context.db_path || context.ag1_db_path || run.db_path || "/files/duckdb/ag1_v4_consensus.duckdb");
const meta = isObj(context.meta) ? context.meta : { initialCapitalEUR: 10000 };
const portfolioSummary = buildPortfolioSummary(context);
const posQtyMap = buildPositionQtyMap(portfolioSummary);
const opportunityMap = Object.fromEntries(
  safeArray(context?.opportunity_pack?.rows)
    .map((row) => [normSymbol(row?.symbol), row])
    .filter(([symbol]) => symbol)
);
const ts = new Date().toISOString();

const proposalItems = items.filter((it) => it !== context && (isObj(it.output) || isObj(it.agentDecision) || Array.isArray(it.output)));
const modelProposals = [];
const votes = [];
const warnings = [];

for (let i = 0; i < proposalItems.length; i += 1) {
  const item = proposalItems[i];
  const modelKey = inferModelKey(item, i);
  const decision = extractDecision(item);
  const actions = safeArray(decision.actions);
  const extractorStatus = String(item.extractorStatus || item.extractor_status || "");
  const parseOk = ["OK_OBJECT", "OK_JSON"].includes(extractorStatus) && Array.isArray(decision.actions);
  modelProposals.push({
    proposal_id: `PROP_${runId}_${modelKey}`,
    run_id: runId,
    ts,
    model_key: modelKey,
    model_name: item.modelName || item.model_name || item.model || modelKey,
    model_id: item.modelId || item.model_id || null,
    extractor_status: extractorStatus || null,
    parse_ok: parseOk,
    decision_json: decision,
    actions_json: actions,
    warnings_json: decision.dataCaveats || item.warnings || [],
    error: parseOk ? null : "No actions array in model output",
  });

  if (!parseOk) {
    warnings.push(`CONSENSUS_MODEL_INVALID:${modelKey}`);
    continue;
  }

  for (let aIdx = 0; aIdx < actions.length; aIdx += 1) {
    const action = actions[aIdx] || {};
    const symbol = normSymbol(action.symbol_internal || action.symbol);
    const rawAction = normAction(action.action);
    const intent = normalizeIntent(rawAction);
    const assetClass = normAssetClass(action.assetClass ?? action.AssetClass);
    const matrix = opportunityMap[symbol] || {};
    const gates = String(matrix.gates || "");
    const buyEligible = intent === "BUY"
      && matrix.decision === "Entrer / Renforcer"
      && (!gates || gates === "OK");
    const sellEligible = intent === "SELL" && (posQtyMap[symbol] || 0) > 0;
    const executable = (buyEligible || sellEligible)
      && symbol
      && !isFxSymbol(action)
      && ["EQUITY", "ETF"].includes(assetClass);
    const vote = {
      vote_id: `VOTE_${runId}_${modelKey}_${symbol || "UNKNOWN"}_${intent}_${aIdx}`,
      run_id: runId,
      ts,
      model_key: modelKey,
      modelKey,
      modelId: item.modelId || item.model_id || null,
      modelName: item.modelName || item.model_name || item.model || modelKey,
      symbol: symbol || "UNKNOWN",
      intent,
      action: rawAction,
      side: sideForIntent(intent),
      executable,
      confidence: pickConfidence(action),
      target_qty: pickTargetQty(action),
      targetQty: pickTargetQty(action),
      target_weight_pct: pickTargetWeightPct(action),
      targetWeightPct: pickTargetWeightPct(action),
      limit_price: pickLimitPrice(action),
      limitPrice: pickLimitPrice(action),
      rationale: clampText(action.rationale, 2048) || null,
      rawAction: action,
      payload_json: action,
    };
    votes.push(vote);
    if (symbol && isFxSymbol(action)) warnings.push(`CONSENSUS_VOTE_IGNORED_FX:${modelKey}:${symbol}`);
  }
}

const validModelCount = modelProposals.filter((p) => p.parse_ok).length;
const groups = new Map();
for (const vote of votes) {
  if (!vote.executable) continue;
  const key = `${vote.symbol}|${vote.intent}`;
  if (!groups.has(key)) groups.set(key, { symbol: vote.symbol, intent: vote.intent, votes: [], validModelCount });
  groups.get(key).votes.push(vote);
}

const consensusDecisions = [];
const approvedActions = [];
for (const group of groups.values()) {
  const uniqueModels = new Set(group.votes.map((v) => v.modelKey));
  if (uniqueModels.size < 2 || validModelCount < 2) {
    const displayModels = group.votes.map(modelDisplayKey).sort();
    consensusDecisions.push({
      consensus_id: `CONS_${runId}_${group.symbol}_${group.intent}`,
      run_id: runId,
      ts,
      symbol: group.symbol,
      intent: group.intent,
      action: group.intent,
      side: sideForIntent(group.intent),
      vote_count: uniqueModels.size,
      valid_model_count: validModelCount,
      model_keys: displayModels.join(","),
      status: "NO_CONSENSUS",
      reason: "Fewer than two valid model votes for the same symbol and intent",
      payload_json: { votes: group.votes, modelKeysCanonical: Array.from(uniqueModels).sort() },
    });
    continue;
  }
  const selected = buildSelectedAction(group, posQtyMap, runId, opportunityMap, portfolioSummary, context.config || {});
  consensusDecisions.push(selected.decision);
  for (const v of group.votes) v.consensus_id = selected.decision.consensus_id;
  if (selected.action) approvedActions.push(selected.action);
}

if (!approvedActions.length) {
  warnings.push(validModelCount < 2 ? "CONSENSUS_NO_TRADE:LESS_THAN_TWO_VALID_MODELS" : "CONSENSUS_NO_TRADE:NO_2_OF_3_EXECUTABLE_AGREEMENT");
  if (!consensusDecisions.length) {
    consensusDecisions.push({
      consensus_id: `CONS_${runId}_GLOBAL_NO_TRADE`,
      run_id: runId,
      ts,
      symbol: "GLOBAL",
      intent: "NO_TRADE",
      action: "NO_TRADE",
      side: null,
      vote_count: 0,
      valid_model_count: validModelCount,
      model_keys: modelProposals.filter((p) => p.parse_ok).map(modelDisplayKey).sort().join(","),
      status: "NO_TRADE",
      reason: warnings[warnings.length - 1],
      payload_json: { modelProposals, votes, modelKeysCanonical: modelProposals.filter((p) => p.parse_ok).map((p) => p.model_key).sort() },
    });
  }
}

const decision = approvedActions.length ? "TRADE" : "NO_TRADE";
const validDecisions = modelProposals.filter((p) => p.parse_ok).map((p) => p.decision_json || {});
const regimeCounts = {};
for (const proposal of validDecisions) {
  const regime = String(proposal.marketRegime || "").toUpperCase();
  if (regime) regimeCounts[regime] = (regimeCounts[regime] || 0) + 1;
}
const selectedRegime = Object.entries(regimeCounts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] || "NEUTRAL";
const targetExposurePct = median(validDecisions.map((p) => toNumOrNull(p.targetExposurePct)).filter((x) => x !== null));
const maxNewPositionVotes = validDecisions.map((p) => toNumOrNull(p.maxNewPositions)).filter((x) => x !== null && x >= 0);
const maxNewPositions = maxNewPositionVotes.length ? Math.floor(Math.min(...maxNewPositionVotes)) : null;
const agentDecision = {
  decisionMeta: {
    runId,
    model: "ag1_v4_consensus",
    strategyVersion: run.strategyVersion || "strategy_v4_consensus",
    validModelCount,
    proposalCount: modelProposals.length,
    consensusRule: "at_least_2_of_3_same_symbol_and_intent",
  },
  portfolioPlan: {
    posture: decision === "TRADE" ? "CONSENSUS_TRADE" : "CONSENSUS_NO_TRADE",
    marketRegime: selectedRegime,
    targetExposurePct,
    maxNewPositions,
  },
  actions: approvedActions,
  riskNotes: warnings,
  dataCaveats: modelProposals.flatMap((p) => safeArray(p.warnings_json)),
  backfillRequests: [],
  consensus: {
    modelProposals,
    votes,
    decisions: consensusDecisions,
  },
};

return [{
  json: {
    decision,
    commentary: `AG1 V4 consensus: ${approvedActions.length} executable action(s), ${validModelCount}/3 valid model outputs`,
    agentDecision,
    modelProposals,
    consensusVotes: votes,
    consensusDecisions,
    orders: [],
    warnings,
    run: { ...run, runId, model: "ag1_v4_consensus", db_path: dbPath },
    config: context.config || {},
    meta,
    portfolioSummary,
    ctx: {
      meta,
      config: context.config || {},
      run: { ...run, runId, model: "ag1_v4_consensus", db_path: dbPath },
      portfolioSummary,
      consensus: agentDecision.consensus,
    },
    transfer_pack: {
      db_path: dbPath,
      run: { ...run, runId, model: "ag1_v4_consensus", db_path: dbPath },
      config: context.config || {},
      meta,
      portfolioSummary,
    },
    db_path: dbPath,
  },
}];
